// تحليل متقدم للنوايا مع نظام نقاط
const analysis = $input.first().json.ai_response;

// حساب درجة أولوية شاملة
let priorityScore = 0;

// إضافة نقاط بناءً على نوع النية
const intentScores = {
  'hajj_substitute': 30,
  'umrah_substitute': 25,
  'inquiry': 10,
  'casual': 5,
  'spam': 0
};
priorityScore += intentScores[analysis.intent_type] || 0;

// إضافة نقاط للاستعجال
const urgencyScores = {
  'high': 25,
  'medium': 15,
  'low': 5
};
priorityScore += urgencyScores[analysis.urgency_level] || 0;

// إضافة نقاط للجدية
priorityScore += (analysis.sincerity_score || 0) * 0.3;

// إضافة نقاط لاحتمال التحويل
priorityScore += (analysis.conversion_probability || 0) * 0.2;

// خصم نقاط للعلامات التحذيرية
if (analysis.red_flags && analysis.red_flags.length > 0) {
  priorityScore -= analysis.red_flags.length * 10;
}

// تحديد التصنيف النهائي
let classification;
if (priorityScore >= 70) {
  classification = 'HOT_LEAD';
} else if (priorityScore >= 50) {
  classification = 'WARM_LEAD';
} else if (priorityScore >= 30) {
  classification = 'COLD_LEAD';
} else {
  classification = 'NOT_QUALIFIED';
}

return {
  ...analysis,
  priority_score: Math.min(100, Math.max(0, priorityScore)),
  classification,
  analyzed_at: new Date().toISOString()
};

